const renderFields = (item: any) => {
    if (!item) return null;

    const Field = ({ label, fKey }: { label: string; fKey: string }) => (
      <div className="space-y-3 group mt-8">
        <label className="text-[11px] font-black text-teal-500 uppercase tracking-widest opacity-70 group-focus-within:opacity-100 transition-opacity">
          {label}
        </label>
        <Textarea
          value={item[fKey] || ""}
          onChange={(e) => handleUpdate(item.id, fKey, e.target.value)}
          placeholder="Typ hier senin antwoord..."
          className="bg-[#0b1233]/40 border-teal-500/20 focus:border-fuchsia-500/50 min-h-[140px] text-teal-50 text-lg leading-relaxed placeholder:text-teal-900/30 transition-all"
        />
      </div>
    );

    switch (item.documentType) {
      case "review":
        return (
          <>
            <Field label="WAT heb jij gemaakt/geleerd?" fKey="geleerd" />
            <Field label="Wat beheers jij nog niet voldoende?" fKey="nietVoldoende" />
            <Field label="Hoe ga jij dit verhelpen: actiepunt ve activiteiten voor volgende Sprint" fKey="actiepunten" />
          </>
        );
      case "retrospective":
        return (
          <>
            <Field label="Wat ging allemaal goed?" fKey="goed" />
            <Field label="Wat kan beter?" fKey="beter" />
            <Field label="Actiepunt voor volgende Sprint" fKey="actiepunt" />
          </>
        );
      case "sprintplan":
        return (
          <>
            <Field label="Sprint Backlog (Grote stappen/samenvatting)" fKey="backlog" />
            <Field label="To Do lijst (Kleine concrete activiteiten - T, D, A, I)" fKey="todo" />
            <Field label="Sprint oplevering (Wat & Wanneer)" fKey="oplevering" />
            <Field label="Definition of Done" fKey="dod" />
          </>
        );
      case "daily":
        return (
          <>
            <Field label="Wat is klaar sinds vorige Daily Scrum?" fKey="klaar" />
            <Field label="Werkt het team volgens planning? (Ja/Nee + Reden/Oplossing)" fKey="planningStatus" />
            <Field label="Zijn er problemen/obstakels?" fKey="obstakels" />
          </>
        );
      case "release":
        return (
          <>
            <Field label="Sprint 1: Welke Userstories?" fKey="s1" />
            <Field label="Sprint 2: Welke Userstories?" fKey="s2" />
            <Field label="Sprint 3: Welke Userstories?" fKey="s3" />
          </>
        );
      default:
        return (
          <div className="py-20 text-center border-2 border-dashed border-teal-500/10 rounded-3xl">
            <p className="text-teal-900 italic">Selecteer bir template om te bewerken.</p>
          </div>
        );
    }
  };